<?php require __DIR__.'/includes/bootstrap.php';requireRole('creator');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}$id=(int)($_POST['event_id']??0);$statement=$pdo->prepare('SELECT * FROM events WHERE event_id=? AND organiser_id=?');$statement->execute([$id,currentUser()['user_id']]);$event=$statement->fetch();if(!$event){http_response_code(403);exit('Event not found.');}if(isset($_POST['add_places'])){$number=filter_var($_POST['add_places'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($number===false){flash('Enter a valid number of places.','error');}else{$pdo->prepare('UPDATE events SET capacity=capacity+? WHERE event_id=?')->execute([$number,$id]);flash('Places added.');}}elseif(($_POST['action']??'')==='cancel'){$pdo->prepare("UPDATE events SET status='removed' WHERE event_id=?")->execute([$id]);flash('Event cancelled and removed from public pages.');}else{http_response_code(400);exit('Invalid action.');}redirect('dashboard.php');
